import { readdirSync, readFileSync, existsSync } from 'node:fs';

const dir = '/home/user/deepseek-harness/.claude/worktrees/agent-a5ee082745114e517/data/proving-ground';
for (const name of readdirSync(dir).sort()) {
  const p = `${dir}/${name}/result.json`;
  if (!existsSync(p)) continue;
  const d = JSON.parse(readFileSync(p, 'utf8'));
  const exp = d.experiment ?? d.result ?? d;
  const out = {
    record: name,
    topKeys: Object.keys(d),
    delta: exp.delta,
    interval: exp.interval,
    verdict: exp.verdict,
    thresholds: exp.thresholds,
    caps: exp.caps,
    arms: exp.arms
      ? Object.fromEntries(
          Object.entries(exp.arms).map(([k, v]) => [
            k,
            { model: v.model, ladder: v.ladder, implementer: v.implementer },
          ]),
        )
      : undefined,
    partial: d.partial ?? d.reason,
  };
  console.log(JSON.stringify(out));
}

